package org.apache.commons.math3.dfp;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_17_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        DfpField field = new DfpField(10); // Assuming a precision of 10
        Dfp dfpValue = new Dfp(field, 1); // Create a Dfp instance with value 1

        int x = Dfp.RADIX; // Use RADIX as the multiplier, which should trigger the bug
        Dfp result = dfpValue.multiply(x);

        // The expected behavior is that the result should be equal to dfpValue * x
        // However, in the pre-fix version, this might not be the case
        Dfp expected = new Dfp(field, x);
        assertEquals("Multiplication result is incorrect for x >= RADIX", expected, result);
    }
}

